insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  18,
  $wyb$A scheduled weekly job that scrapes each competitor's website, recent news, and job listings, asks the AI to infer strategic moves against a fixed threat-level rubric, and emails a structured briefing to leadership every Monday morning. A threat-level guard normalizes whatever the AI actually writes back against that rubric, so rankings stay comparable across competitors instead of silently drifting between calls.$wyb$,
  $wyl$[
  "Scrape multiple data sources per competitor, with the parsing logic separated from the live fetch so it's testable offline",
  "Filter noisy HTML (careers pages, navigation junk) down to real signal with tested rules",
  "Give the AI a fixed rubric instead of an open-ended judgment call, then validate its answer against that exact rubric in code",
  "Design a 5-section synthesis prompt using bracket markers instead of JSON",
  "Generate an executive summary across multiple analyses in one AI call",
  "Format and send an HTML email, and schedule a weekly recurring job"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.7 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "120 min",
  "buildCount": 3,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A free Tavily API key (tavily.com - 1,000 searches/month free)",
    "An email account you can send from (e.g. Gmail with an App Password)"
  ],
  "outcomes": [
    "Maintain a watchlist of 3-5 competitors with their site and careers page",
    "Pull homepage text, recent news, and job postings for each one, with parsing tested offline before ever hitting a live site",
    "Have the AI infer strategic moves against a fixed rubric, with a guard that catches an inconsistent threat-level answer",
    "Generate an executive summary across all competitors in one AI call",
    "Get a structured weekly briefing emailed to you, on a schedule"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Build your watchlist and gather raw intel",
      "time": "45 min",
      "description": "Get raw data on each competitor before asking the AI to make sense of it.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# gemini-3.7-flash first - the current stable/GA flash model. If it's\n# ever down (Google's free tier occasionally returns 503 \"high demand\"\n# on a single model for hours at a time), gemini-2.5-flash is a real\n# fallback, not a downgrade-and-forget: a different model is a\n# different capacity pool, so it's often still up during a\n# 3.7-specific outage. Set GEMINI_MODEL in .env to pin one specific\n# model instead and skip the fallback entirely.\n_env_model = os.environ.get(\"GEMINI_MODEL\")\nGEMINI_MODELS = [_env_model] if _env_model else [\"gemini-3.7-flash\", \"gemini-2.5-flash\"]\nGEMINI_URL_TEMPLATE = \"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent\"\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini_model(model, api_key, payload):\n    \"\"\"\n    Tries ONE Gemini model, retrying up to MAX_ATTEMPTS times on a 503\n    (\"high demand\") before giving up on this model. Returns the parsed\n    result dict, or raises AIError - including a distinct AIError for a\n    503 that never cleared, so _ask_gemini() below can tell \"this model\n    is down, try the next one\" apart from every other failure.\n    \"\"\"\n    url = GEMINI_URL_TEMPLATE.format(model=model)\n\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(url, params={\"key\": api_key}, json=payload, timeout=90)\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            if attempt < MAX_ATTEMPTS - 1:\n                time.sleep(RETRY_DELAY_SECONDS)\n                continue\n            raise AIError(f\"{model} is busy (503 - high demand)\")\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    # Try each model in GEMINI_MODELS in order - a 503 that survives every\n    # retry on one model falls through to the next, since a different\n    # model is a different capacity pool and is often still up during a\n    # model-specific outage. Any other kind of failure (bad key, rate\n    # limit, safety block) is raised immediately instead of wasted on a\n    # second model that would fail the exact same way.\n    last_problem = None\n    for model in GEMINI_MODELS:\n        try:\n            return _ask_gemini_model(model, api_key, payload)\n        except AIError as problem:\n            if \"high demand\" not in str(problem):\n                raise\n            last_problem = problem\n\n    raise AIError(\n        f\"Gemini was unavailable after trying {', '.join(GEMINI_MODELS)} ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with ONE of the two setups below — pick whichever you're using, then replace the placeholder with your real key:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n\n# Tavily search - free tier gives you 1,000 searches/month\nTAVILY_API_KEY=tvly-paste_your_own_key_here\n\n# Gmail App Password (myaccount.google.com/apppasswords) - NOT your\n# normal account password\nSMTP_USER=you@gmail.com\nSMTP_PASS=paste_your_16_char_app_password_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create `competitors.json` listing 3-5 competitors, each with name, website, and jobs_url (their careers page):",
          "prompt": "[\n  {\n    \"name\": \"Acme Corp\",\n    \"website\": \"https://example.com\",\n    \"jobs_url\": \"https://example.com/careers\"\n  }\n]\n",
          "verify": "Confirm the file is valid JSON (run `python -c \"import json; json.load(open('competitors.json'))\"` - no output means it parsed fine) and every website/jobs_url actually opens in your browser."
        },
        {
          "instruction": "Create `scrape.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Competitor Intelligence Monitor (part 1).\n\nFetches a competitor's homepage as plain text and their recent news via\nTavily. The text-cleaning and news-parsing helpers are pure functions\nwith no network call in them, tested below against fake data - only the\nlive fetch functions themselves need a real network call.\n\"\"\"\n\nimport os\nimport re\n\nimport requests\nfrom bs4 import BeautifulSoup\nfrom dotenv import load_dotenv\nfrom tavily import TavilyClient\n\nload_dotenv()\n\nBROWSER_HEADER = {\"User-Agent\": \"Mozilla/5.0 (compatible; CompetitorMonitor/1.0)\"}\nNOT_THE_CONTENT = [\"script\", \"style\", \"nav\", \"footer\", \"header\", \"aside\", \"form\"]\n\n# Stop after this many characters of homepage text. A MONEY decision:\n# analyze.py sends this straight into a prompt alongside news and job\n# data for every competitor on your watchlist - a full homepage's raw\n# text costs real tokens for content that's mostly navigation and legal\n# boilerplate anyway.\nMAX_HOMEPAGE_CHARS = 3000\n\nNEWS_MAX_RESULTS = 5\n\n\ndef clean_html_text(html, max_chars=MAX_HOMEPAGE_CHARS):\n    \"\"\"\n    Turns raw page HTML into plain, readable text, capped at max_chars.\n\n    Pure function, no network call - which is why the self-test below\n    can check it thoroughly against HTML you already have.\n    \"\"\"\n    soup = BeautifulSoup(html, \"html.parser\")\n    for junk in soup(NOT_THE_CONTENT):\n        junk.decompose()\n\n    text = re.sub(r\"\\s+\", \" \", soup.get_text(separator=\" \")).strip()\n    return text[:max_chars]\n\n\ndef get_homepage_text(url):\n    \"\"\"\n    Fetches url and returns its cleaned text, or \"\" if anything goes\n    wrong - a blocked or slow competitor site should never take down\n    the whole weekly run over one company.\n    \"\"\"\n    try:\n        response = requests.get(url, headers=BROWSER_HEADER, timeout=10)\n        response.raise_for_status()\n    except requests.RequestException:\n        return \"\"\n    return clean_html_text(response.text)\n\n\ndef _parse_news_results(raw_results):\n    \"\"\"\n    Turns Tavily's raw result list into the simple shape this project\n    uses everywhere: [{\"title\": \"...\", \"snippet\": \"...\"}, ...]\n\n    Pure function - tested below without hitting Tavily.\n    \"\"\"\n    parsed = []\n    for item in raw_results:\n        title = item.get(\"title\", \"\").strip()\n        if not title:\n            continue\n        parsed.append({\"title\": title, \"snippet\": item.get(\"content\", \"\").strip()[:300]})\n    return parsed\n\n\ndef get_recent_news(name, max_results=NEWS_MAX_RESULTS):\n    \"\"\"Searches Tavily for \"{name} news this week\" and returns parsed results.\"\"\"\n    api_key = os.environ.get(\"TAVILY_API_KEY\")\n    if not api_key:\n        raise RuntimeError(\"No TAVILY_API_KEY found. Get a free key at tavily.com and add it to .env.\")\n\n    client = TavilyClient(api_key=api_key)\n    response = client.search(query=f\"{name} news this week\", max_results=max_results)\n    return _parse_news_results(response.get(\"results\", []))\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the pure parsing works - no\n    # network call, no API key needed:  python scrape.py\n    print(\"Checking clean_html_text()...\")\n    fake_html = \"\"\"\n    <html><body>\n      <nav>Home | About | Careers</nav>\n      <main><h1>Acme Corp</h1><p>We build the future of widgets.</p></main>\n      <footer>Copyright 2026</footer>\n    </body></html>\n    \"\"\"\n    text = clean_html_text(fake_html)\n    assert \"Home | About\" not in text\n    assert \"Copyright\" not in text\n    assert \"future of widgets\" in text\n    print(\"  OK -\", repr(text))\n\n    print(\"\\nChecking _parse_news_results()...\")\n    fake_results = [\n        {\"title\": \"Acme raises Series B\", \"content\": \"Acme Corp announced a $20M raise...\"},\n        {\"title\": \"\", \"content\": \"should be skipped, has no title\"},\n    ]\n    parsed = _parse_news_results(fake_results)\n    assert len(parsed) == 1\n    assert parsed[0][\"title\"] == \"Acme raises Series B\"\n    print(\"  OK - result with no title correctly skipped:\", parsed)\n\n    print(\"\\nAll parsing checks passed.\")\n",
          "verify": "Run `python scrape.py` (no network call, no API key needed - this only tests the parsing helpers against fake HTML/results). You should see junk correctly stripped from fake homepage HTML and a result with no title correctly skipped, ending with `All parsing checks passed.`"
        },
        {
          "instruction": "Create `jobs.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Competitor Intelligence Monitor (part 2).\n\nPulls job titles off a competitor's careers page - a hiring pattern\n(3 open \"ML Engineer\" roles, say) is often a stronger strategic signal\nthan anything on their homepage. The title-filtering logic is pure and\ntested below; only the live page fetch needs a real network call.\n\"\"\"\n\nimport requests\nfrom bs4 import BeautifulSoup\n\nfrom scrape import BROWSER_HEADER\n\nMIN_TITLE_LENGTH = 5\nMAX_TITLE_LENGTH = 80\nMAX_TITLES = 30\n\n# A careers page's h2/h3/a tags mix real job titles (\"Senior Backend\n# Engineer\") with site furniture (\"Careers\", \"Apply now\"). Length alone\n# doesn't catch every case (\"Careers\" is 7 characters, well within a\n# normal title's length) - this explicit list catches the common nav\n# words that length filtering alone would miss.\nNAV_JUNK_WORDS = {\"careers\", \"jobs\", \"apply\", \"apply now\", \"home\", \"about\", \"about us\", \"contact\"}\n\n\ndef parse_job_titles(html):\n    \"\"\"\n    Pulls candidate job titles out of raw careers-page HTML: the text of\n    every h2, h3, and a tag, kept only if it isn't obvious navigation\n    text and its length is between MIN_TITLE_LENGTH and MAX_TITLE_LENGTH\n    characters.\n\n        parse_job_titles(\"<h2>Senior Backend Engineer</h2>...\")\n        -> [\"Senior Backend Engineer\", ...]\n\n    De-duplicates (a title often appears as both a heading and a link on\n    the same page) and caps at MAX_TITLES, since a large careers page\n    can list hundreds of roles and the strategic signal is in the\n    PATTERN, not every single listing.\n    \"\"\"\n    soup = BeautifulSoup(html, \"html.parser\")\n    candidates = soup.find_all([\"h2\", \"h3\", \"a\"])\n\n    titles = []\n    seen = set()\n    for tag in candidates:\n        text = tag.get_text(strip=True)\n        if text.lower() in NAV_JUNK_WORDS:\n            continue\n        if MIN_TITLE_LENGTH <= len(text) <= MAX_TITLE_LENGTH and text not in seen:\n            titles.append(text)\n            seen.add(text)\n        if len(titles) >= MAX_TITLES:\n            break\n\n    return titles\n\n\ndef get_job_titles(jobs_url):\n    \"\"\"\n    Fetches jobs_url and returns up to MAX_TITLES candidate job titles,\n    or an empty list if anything goes wrong - including a JS-rendered\n    careers page returning no usable HTML text at all, a real and common\n    limitation of a simple requests-based scraper, not a bug to fix here.\n    \"\"\"\n    try:\n        response = requests.get(jobs_url, headers=BROWSER_HEADER, timeout=10)\n        response.raise_for_status()\n    except requests.RequestException:\n        return []\n    return parse_job_titles(response.text)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the title-filtering logic works\n    # - no network call needed:  python jobs.py\n    fake_html = \"\"\"\n    <html><body>\n      <h2>Careers</h2>\n      <h3>Senior Backend Engineer</h3>\n      <h3>ML</h3>\n      <a href=\"/apply\">Apply now</a>\n      <a href=\"/jobs/pm\">Senior Product Manager - Platform</a>\n      <h3>Senior Backend Engineer</h3>\n    </body></html>\n    \"\"\"\n    titles = parse_job_titles(fake_html)\n    print(\"Parsed titles:\", titles)\n\n    assert \"Senior Backend Engineer\" in titles\n    assert titles.count(\"Senior Backend Engineer\") == 1\n    assert \"Senior Product Manager - Platform\" in titles\n    assert \"ML\" not in titles\n    assert \"Careers\" not in titles\n    assert \"Apply now\" not in titles\n    print(\"  OK - short entries, duplicates, and nav junk all correctly filtered\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python jobs.py`. You should see real job titles correctly kept, a duplicate correctly de-duplicated, and short/nav-junk entries ('ML', 'Careers', 'Apply now') all correctly filtered out, ending with `All checks passed.`"
        },
        {
          "instruction": "Now run all three live functions against one real competitor from your watchlist:",
          "prompt": "python -c \"from scrape import get_homepage_text, get_recent_news; from jobs import get_job_titles; print(get_homepage_text('https://example.com')[:300]); print(get_recent_news('Acme Corp')); print(get_job_titles('https://example.com/careers'))\"",
          "verify": "You should get back readable homepage text, a list of news snippets, and a list of job titles. If the careers page returns an empty list, note it - that competitor likely uses a JS-rendered careers page, which a simple scraper can't read (a real, documented limitation, not a bug)."
        }
      ],
      "goFurther": "For any competitor whose job titles list comes back empty, search '[competitor name] careers' on LinkedIn manually and paste those titles into a small jobs_fallback.json as a manual override for Build 2."
    },
    {
      "number": 2,
      "title": "Have the AI analyze each competitor - with a threat-level guard",
      "time": "35 min",
      "description": "Turn raw scraped data into actual strategic signals. The AI is given a fixed rubric instead of an open-ended judgment call, and its answer is checked against that exact rubric before it ever reaches the briefing.",
      "steps": [
        {
          "instruction": "Create `analyze.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the Competitor Intelligence Monitor.\n\nTurns raw scraped data into strategic signals. Also carries this\nproject's safety guard: the AI is given a fixed threat-level rubric\ninstead of an open-ended judgment call, and whatever it writes back is\nvalidated against that exact rubric - not just trusted as-is.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\nTHREAT_LEVELS = [\"LOW\", \"MEDIUM\", \"HIGH\"]\n\n# Giving the AI a FIXED rubric (not \"judge the threat level\") is what\n# keeps rankings comparable across competitors run in the same batch -\n# an open-ended judgment call tends to drift between calls even on\n# genuinely similar inputs.\nTHREAT_RUBRIC = \"\"\"Use this exact rubric to choose a threat level:\nLOW    - no notable recent activity, hiring is flat or unrelated to your market\nMEDIUM - some notable activity (a funding round, a few relevant hires) but no clear new direction\nHIGH   - a clear strategic shift (multiple hires in one new area, a funding round paired with related news)\"\"\"\n\nSECTION_NAMES = [\"WHATSNEW\", \"SIGNALS\", \"THREAT\", \"REASONING\", \"OPPORTUNITIES\"]\n\n\ndef build_prompt(name, homepage_text, news, job_titles):\n    news_block = \"\\n\".join(f\"- {n['title']}: {n['snippet']}\" for n in news) or \"(no recent news found)\"\n    jobs_block = \"\\n\".join(f\"- {t}\" for t in job_titles) or \"(no job titles found - careers page may be JS-rendered)\"\n\n    return f\"\"\"Competitor: {name}\n\nHomepage text:\n{homepage_text or \"(homepage could not be fetched)\"}\n\nRecent news:\n{news_block}\n\nOpen job titles:\n{jobs_block}\n\n{THREAT_RUBRIC}\n\nFormat your answer EXACTLY like this:\n\n[WHATSNEW]\nwhat's new this week, specific to the news/homepage above\n\n[SIGNALS]\nstrategic signals - explicitly reason about what the job titles suggest,\nciting specific titles where relevant\n\n[THREAT]\none word: LOW, MEDIUM, or HIGH\n\n[REASONING]\none sentence justifying the threat level using the rubric above\n\n[OPPORTUNITIES]\nopportunities this creates for us\n\n[END]\n\nBe specific - reference actual job titles or news items, not generic\nstatements. Do not invent news or hires that weren't given to you above.\"\"\"\n\n\ndef validate_threat_level(raw_value):\n    \"\"\"\n    Normalizes the AI's threat-level text against the fixed rubric.\n\n        validate_threat_level(\"Moderate risk\") -> \"UNCLEAR\"\n        validate_threat_level(\"high.\") -> \"HIGH\"\n\n    Real models occasionally answer \"Moderate\" or \"High risk\" instead of\n    the exact word asked for - rather than silently accepting whatever\n    comes back (which is exactly how threat rankings end up\n    inconsistent across competitors), anything that doesn't cleanly\n    contain one of LOW/MEDIUM/HIGH is normalized to \"UNCLEAR\" so it's\n    visibly flagged in the briefing instead of quietly miscategorized.\n    \"\"\"\n    cleaned = raw_value.strip().upper().rstrip(\".\")\n    for level in THREAT_LEVELS:\n        if level in cleaned:\n            return level\n    return \"UNCLEAR\"\n\n\ndef parse_analysis(reply):\n    \"\"\"\n    Turns the AI's marker-formatted reply into a dict of sections, with\n    THREAT run through validate_threat_level().\n\n    Same forgiving [MARKER] approach used throughout this course.\n    Returns {} if no recognised markers were found at all.\n    \"\"\"\n    sections = {name: [] for name in SECTION_NAMES}\n    current = None\n\n    for raw_line in reply.splitlines():\n        line = raw_line.strip()\n        marker = line.strip(\"[]\").upper()\n        is_marker = line.startswith(\"[\") and line.endswith(\"]\")\n\n        if is_marker and marker == \"END\":\n            break\n        if is_marker and marker in sections:\n            current = marker\n            continue\n        if current is None:\n            continue\n        if line.startswith(\"```\"):\n            continue\n        if line:\n            sections[current].append(line)\n\n    if not any(sections.values()):\n        return {}\n\n    result = {name: \"\\n\".join(lines).strip() for name, lines in sections.items()}\n    result[\"THREAT\"] = validate_threat_level(result[\"THREAT\"]) if result[\"THREAT\"] else \"UNCLEAR\"\n    return result\n\n\ndef analyze_competitor(name, homepage_text, news, job_titles):\n    \"\"\"\n    The main function. Give it one competitor's raw data, get back a\n    dict with WHATSNEW, SIGNALS, THREAT, REASONING, and OPPORTUNITIES.\n    \"\"\"\n    prompt = build_prompt(name, homepage_text, news, job_titles)\n    reply = ask_ai(prompt, max_tokens=800, project=\"competitor-intelligence-monitor\")\n\n    analysis = parse_analysis(reply)\n    if not analysis:\n        raise ValueError(\n            \"The AI replied, but not in the format we asked for.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n    return analysis\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check parsing and the threat-level\n    # guard work - no AI call, no credits spent:  python analyze.py\n\n    print(\"Checking a well-formed reply with a clean threat level...\")\n    good_reply = \"\"\"[WHATSNEW]\nAcme announced a new enterprise pricing tier this week.\n\n[SIGNALS]\nThree open \"ML Platform Engineer\" roles suggest a push into AI features.\n\n[THREAT]\nHIGH\n\n[REASONING]\nMultiple ML-focused hires paired with a new enterprise tier signal a clear new direction.\n\n[OPPORTUNITIES]\nWe should highlight our existing AI features in competitive deals now.\n\n[END]\"\"\"\n    result = parse_analysis(good_reply)\n    assert result[\"THREAT\"] == \"HIGH\"\n    assert \"ML Platform Engineer\" in result[\"SIGNALS\"]\n    print(\"  OK - all 5 sections parsed, THREAT correctly normalized to HIGH\")\n\n    print(\"\\nChecking a reply where the AI ignores the exact wording ('Moderate risk')...\")\n    messy_reply = \"\"\"[WHATSNEW]\nNothing major this week.\n\n[SIGNALS]\nHiring looks flat.\n\n[THREAT]\nModerate risk, leaning medium\n\n[REASONING]\nNo major changes detected.\n\n[OPPORTUNITIES]\nNone significant.\n\n[END]\"\"\"\n    result = parse_analysis(messy_reply)\n    assert result[\"THREAT\"] == \"MEDIUM\"\n    print(\"  OK - 'Moderate risk, leaning medium' correctly normalized to MEDIUM\")\n\n    print(\"\\nChecking a threat level with no recognisable rubric word at all...\")\n    assert validate_threat_level(\"uncertain\") == \"UNCLEAR\"\n    print(\"  OK - an unrecognisable threat level is flagged UNCLEAR instead of silently guessed\")\n\n    print(\"\\nChecking a reply with no recognisable markers at all...\")\n    assert parse_analysis(\"Sorry, I can't analyze that.\") == {}\n    print(\"  OK - returned {} instead of crashing\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python analyze.py` (no AI call, no credits spent - this only tests parsing and the threat-level guard against fake replies). You should see a clean HIGH threat correctly parsed, 'Moderate risk, leaning medium' correctly normalized to MEDIUM, a totally unrecognisable threat level correctly flagged UNCLEAR, and a no-markers reply correctly returning {} - ending with `All checks passed.`"
        },
