    {
      "number": 3,
      "title": "Assemble the weekly briefing and schedule it",
      "time": "40 min",
      "description": "Turn per-competitor analyses into one polished email leadership will actually read.",
      "steps": [
        {
          "instruction": "Create `briefing.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Competitor Intelligence Monitor (part 1) - combines\nper-competitor analyses into one Markdown briefing, with an executive\nsummary generated across all of them.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\nSECTION_TITLES = {\n    \"WHATSNEW\": \"What's New\",\n    \"SIGNALS\": \"Strategic Signals\",\n    \"THREAT\": \"Threat Level\",\n    \"REASONING\": \"Reasoning\",\n    \"OPPORTUNITIES\": \"Opportunities\",\n}\n\n\ndef _format_analysis(analysis):\n    lines = []\n    for key, title in SECTION_TITLES.items():\n        lines.append(f\"**{title}:** {analysis.get(key, '(not available)')}\")\n    return \"\\n\\n\".join(lines)\n\n\ndef build_briefing(analyses, exec_summary=\"\"):\n    \"\"\"\n    Turns {\"Acme\": {...analysis dict...}, \"Globex\": {...}} into one\n    Markdown document.\n\n        markdown = build_briefing(analyses, exec_summary)\n\n    Pure function - tested below without any AI call.\n    \"\"\"\n    lines = [\"# Weekly Competitive Intelligence Briefing\", \"\"]\n    if exec_summary:\n        lines.append(\"## Executive Summary\")\n        lines.append(exec_summary)\n        lines.append(\"\")\n\n    for name, analysis in analyses.items():\n        lines.append(f\"## {name}\")\n        lines.append(_format_analysis(analysis))\n        lines.append(\"\")\n\n    return \"\\n\".join(lines)\n\n\ndef generate_exec_summary(analyses):\n    \"\"\"\n    Sends all the analyses to the AI in one call and asks for a 3-4\n    sentence executive summary across every competitor.\n    \"\"\"\n    combined = \"\\n\\n\".join(\n        f\"{name}: threat={a.get('THREAT', 'UNCLEAR')}. {a.get('WHATSNEW', '')}\"\n        for name, a in analyses.items()\n    )\n    prompt = f\"\"\"Below is this week's per-competitor intelligence. Write a 3-4\nsentence executive summary across ALL of them for a leadership team who\nwon't read the full briefing.\n\n{combined}\"\"\"\n\n    return ask_ai(prompt, max_tokens=250, project=\"competitor-intelligence-monitor\")\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the Markdown assembly works - no\n    # AI call, no credits spent:  python briefing.py\n    sample_analyses = {\n        \"Acme Corp\": {\n            \"WHATSNEW\": \"Announced a new pricing tier.\",\n            \"SIGNALS\": \"Hiring ML engineers.\",\n            \"THREAT\": \"HIGH\",\n            \"REASONING\": \"Clear new direction.\",\n            \"OPPORTUNITIES\": \"Highlight our AI features.\",\n        },\n        \"Globex Inc\": {\n            \"WHATSNEW\": \"Nothing notable.\",\n            \"SIGNALS\": \"Flat hiring.\",\n            \"THREAT\": \"LOW\",\n            \"REASONING\": \"No changes detected.\",\n            \"OPPORTUNITIES\": \"None significant.\",\n        },\n    }\n    markdown = build_briefing(\n        sample_analyses,\n        exec_summary=\"Overall, low competitive movement this week except Acme's new AI push.\",\n    )\n    print(markdown)\n\n    assert \"# Weekly Competitive Intelligence Briefing\" in markdown\n    assert \"## Executive Summary\" in markdown\n    assert \"## Acme Corp\" in markdown\n    assert \"## Globex Inc\" in markdown\n    assert \"**Threat Level:** HIGH\" in markdown\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python briefing.py` (no AI call for the Markdown assembly check - only generate_exec_summary() needs one, and it's exercised for real in main.py). You should see the full Markdown briefing printed with an executive summary section and one section per competitor, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `email_format.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Competitor Intelligence Monitor (part 2) - converts the\nMarkdown briefing to a styled HTML email.\n\"\"\"\n\nimport markdown as markdown_lib\n\nEMAIL_CSS = \"\"\"\nbody { font-family: -apple-system, Arial, sans-serif; color: #1a1a1a; max-width: 700px; margin: 0 auto; }\nh1 { font-size: 1.5em; } h2 { font-size: 1.2em; border-bottom: 1px solid #ddd; padding-bottom: 4px; }\n\"\"\"\n\n\ndef to_html_email(markdown_text):\n    \"\"\"\n    Turns the Markdown briefing into a full HTML document ready to send\n    as an email body.\n\n        html = to_html_email(markdown_text)\n\n    Pure function - tested below without sending any real email.\n    \"\"\"\n    body_html = markdown_lib.markdown(markdown_text)\n    return f\"<html><head><style>{EMAIL_CSS}</style></head><body>{body_html}</body></html>\"\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check Markdown-to-HTML conversion\n    # works:  python email_format.py\n    sample_markdown = \"# Weekly Briefing\\n\\n## Acme Corp\\n\\n**Threat Level:** HIGH\"\n    html = to_html_email(sample_markdown)\n\n    assert \"<h1>Weekly Briefing</h1>\" in html\n    assert \"<h2>Acme Corp</h2>\" in html\n    assert \"<strong>Threat Level:</strong> HIGH\" in html\n    print(html)\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python email_format.py`. You should see the sample Markdown correctly converted to HTML with real <h1>/<h2>/<strong> tags, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `main.py` with this code, then run it end-to-end:",
          "prompt": "\"\"\"\nStep 3 of the Competitor Intelligence Monitor (part 3) - the command you\nactually run, ideally every Monday morning.\n\nRun it with:  python main.py\n\"\"\"\n\nimport json\nimport os\nimport smtplib\nfrom email.mime.multipart import MIMEMultipart\nfrom email.mime.text import MIMEText\n\nfrom analyze import analyze_competitor\nfrom briefing import build_briefing, generate_exec_summary\nfrom dotenv import load_dotenv\nfrom email_format import to_html_email\nfrom jobs import get_job_titles\nfrom scrape import get_homepage_text, get_recent_news\nfrom sdt_ai import AIError\n\nload_dotenv()\n\n\ndef gather_and_analyze(competitor):\n    name = competitor[\"name\"]\n    print(f\"Gathering data for {name}...\")\n    homepage_text = get_homepage_text(competitor[\"website\"])\n    news = get_recent_news(name)\n    job_titles = get_job_titles(competitor[\"jobs_url\"])\n\n    print(f\"Analyzing {name}...\")\n    return analyze_competitor(name, homepage_text, news, job_titles)\n\n\ndef send_email(html_body, subject=\"Weekly Competitive Intelligence Briefing\"):\n    smtp_user = os.environ[\"SMTP_USER\"]\n    smtp_pass = os.environ[\"SMTP_PASS\"]\n\n    message = MIMEMultipart(\"alternative\")\n    message[\"Subject\"] = subject\n    message[\"From\"] = smtp_user\n    message[\"To\"] = smtp_user\n    message.attach(MIMEText(html_body, \"html\"))\n\n    with smtplib.SMTP_SSL(\"smtp.gmail.com\", 465) as server:\n        server.login(smtp_user, smtp_pass)\n        server.send_message(message)\n\n\nif __name__ == \"__main__\":\n    with open(\"competitors.json\", encoding=\"utf-8\") as f:\n        competitors = json.load(f)\n\n    analyses = {}\n    for competitor in competitors:\n        try:\n            analyses[competitor[\"name\"]] = gather_and_analyze(competitor)\n        except (AIError, ValueError) as problem:\n            print(f\"  Skipped {competitor['name']}: {problem}\")\n\n    if not analyses:\n        print(\"No competitors were successfully analyzed - nothing to send.\")\n    else:\n        print(\"Generating executive summary...\")\n        exec_summary = generate_exec_summary(analyses)\n        markdown_briefing = build_briefing(analyses, exec_summary)\n        html = to_html_email(markdown_briefing)\n\n        send_email(html)\n        print(f\"\\nDone. Briefing sent covering {len(analyses)} competitor(s).\")\n",
